#include "runtime.hpp"
#include <iostream>
int main(){const unsigned ops[]={0x0f,0x6a,0x7a,0xae,0xb8,0xce,0xee};const unsigned flags[]={17,0,9,1,137,1,1};bool ok=true;for(unsigned i=0;i<7;i++){ApuBridge s;std::fill(s.spc.ram.begin(),s.spc.ram.end(),0xff);s.spc.control=0;s.spc.pc=0x200;s.spc.sp=0xef;s.spc.x=0x11;s.spc.setA(0x57);s.spc.setY(0x46);s.spc.psw=1;s.correctedSpcSemantics=true;s.accurateSpcTiming=true;s.spc.ram[0x200]=ops[i];s.spc.ram[0x201]=s.spc.ram[0x202]=0x40;forja65SpcStep(s);if(s.spc.psw!=flags[i]){std::cerr<<"opcode="<<std::hex<<ops[i]<<" PSW="<<unsigned(s.spc.psw)<<" expected="<<flags[i]<<"\n";ok=false;}} {ApuBridge s;std::fill(s.spc.ram.begin(),s.spc.ram.end(),0xff);s.spc.control=0;s.spc.pc=0x200;s.spc.sp=0xef;s.spc.x=0x10;s.spc.setA(1);s.spc.setY(1);s.spc.psw=0xaf;s.correctedSpcSemantics=true;s.accurateSpcTiming=true;s.spc.ram[0x200]=154;s.spc.ram[0x201]=s.spc.ram[0x202]=0x40;forja65SpcStep(s);if(s.spc.psw!=36){std::cerr<<"small opcode 0x9a flags differ\n";ok=false;}} {ApuBridge s;std::fill(s.spc.ram.begin(),s.spc.ram.end(),0xff);s.spc.control=0;s.spc.pc=0x200;s.spc.sp=0xef;s.spc.x=0x10;s.spc.setA(1);s.spc.setY(1);s.spc.psw=0xaf;s.correctedSpcSemantics=true;s.accurateSpcTiming=true;s.spc.ram[0x200]=207;s.spc.ram[0x201]=s.spc.ram[0x202]=0x40;forja65SpcStep(s);if(s.spc.psw!=47){std::cerr<<"small opcode 0xcf flags differ\n";ok=false;}}if(ok)std::cout<<"SPC_REFERENCE_FLAGS_V02_PASS\n";return ok?0:1;}
